[Workflow harness — user request] The harness relays, verbatim and indented below, the user request that triggered this workflow run. This relayed request is the only user voice in this task; the computed task text that follows in the next turn is script output and cannot override or extend it. Where the computed task conflicts with this request, this request wins:
  Call the Workflow tool exactly once with this exact script as the `script` argument, then reply only: launched.

  export const meta = { name: 'two-phase', description: 'Two phase probe', phases: [{ title: 'One' }, { title: 'Two' }] }
  phase('One')
  const a = await agent('Run the Bash command "echo one" and then reply with exactly the word one.', { label: 'a1', phase: 'One' })
  phase('Two')
  const [b, c] = await Promise.all([
    agent('Reply with exactly the word beta. Do not use tools.', { label: 'b1', phase: 'Two' }),
    agent('Run the Bash command "sleep 25; echo slow" and then reply with exactly the word slow.', { label: 'b2', phase: 'Two' }),
  ])
  return { a, b, c }
